descriptor.templateCss:
:host{display:block;width:100%;height:100%;min-width:0;min-height:0;overflow:hidden}
*{box-sizing:border-box}
.tm-root{--tm-bg:#111820;--tm-panel:#17232e;--tm-text:#edf3f8;--tm-muted:#9aa9b8;--tm-track:#34414d;--tm-accent:#f2c300;--tm-metal-dark:#667482;--tm-metal-mid:#b7c2cc;--tm-metal-light:#e6edf2;--tm-grid:rgba(255,255,255,.25);--tm-soil:#5a4632;--tm-soil-line:#8a6d46;--tm-glass:rgba(8,14,20,.55);--tm-rail:#f2c300;--tm-gauge:#f4f7fa;--tm-plastic:#e4eaef;--tm-cage:#8794a1;--tm-cab:#eef2f5;--tm-grass:#58a83a;--tm-grass-dark:#3b7a28;--tm-concrete:#8d98a3;--tm-concrete-light:#aab4bd;--tm-wall:#e6ecf1;--tm-inner:#6f7b86;width:100%;height:100%;padding:10px 13px;display:flex;flex-direction:column;gap:7px;overflow:hidden;border-radius:inherit;background:transparent;color:var(--tm-text);font-family:Roboto,Arial,sans-serif;position:relative}
.tm-industrial{background:linear-gradient(145deg,#17232e,#101820);--tm-accent:#f2c300}
.tm-light{background:linear-gradient(145deg,#fff,#f3f6f9);--tm-bg:#fff;--tm-panel:#f7f9fb;--tm-text:#263445;--tm-muted:#778596;--tm-track:#dce3ea;--tm-accent:#d99a00;--tm-metal-dark:#8b98a5;--tm-metal-mid:#c4cdd5;--tm-metal-light:#eef2f5;--tm-grid:rgba(38,52,69,.2);--tm-soil:#b89d7a;--tm-soil-line:#8c7152;--tm-glass:rgba(120,140,160,.38);--tm-rail:#e0a800;--tm-plastic:#f4f7fa;--tm-cage:#7d8a97;--tm-cab:#ffffff;--tm-concrete:#b4bdc6;--tm-concrete-light:#cdd5dc;--tm-wall:#f7f9fb;--tm-inner:#98a4af}
.tm-header{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:23px;flex:0 0 auto}
.tm-heading{display:flex;align-items:center;gap:8px;min-width:0}
.tm-header-icon{display:inline-flex;align-items:center;justify-content:center;color:var(--tm-accent);flex:0 0 auto;width:32px;height:32px;border-radius:9px;background:rgba(242,195,0,.10);border:1px solid rgba(242,195,0,.18)}
.tm-light .tm-header-icon{background:rgba(217,154,0,.10);border-color:rgba(217,154,0,.25)}
.tm-icon-svg{width:24px;height:24px;display:block;overflow:visible}
.tm-header-icon .mat-icon,.tm-header-icon mat-icon,.tm-header-icon tb-icon{font-size:20px;width:20px;height:20px;color:inherit}
.tm-title{font-size:13px;font-weight:700;letter-spacing:.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tm-online{font-size:9px;font-weight:750;letter-spacing:.45px;color:#31c77b;white-space:nowrap;display:flex;align-items:center;gap:5px}
.tm-online i,.tm-state i{width:7px;height:7px;border-radius:50%;display:inline-block;background:currentColor}
.tm-online.offline{color:#e45a54}
.tm-main{display:flex;align-items:center;justify-content:space-around;gap:8px;flex:1 1 auto;min-height:0}
.tm-illustration{height:100%;min-height:90px;flex:1 1 58%;min-width:0;display:flex;align-items:center;justify-content:center}
.tm-svg{width:100%;height:100%;max-height:220px;overflow:visible;filter:drop-shadow(0 3px 5px rgba(0,0,0,.35))}
.tm-reading{flex:0 1 42%;min-width:95px;display:flex;flex-direction:column;justify-content:center;gap:3px}
.tm-reading-label{font-size:10px;color:var(--tm-muted);font-weight:600}
.tm-value-line{display:flex;align-items:baseline;gap:4px;white-space:nowrap}
.tm-value{font-size:clamp(25px,5vw,43px);font-weight:800;line-height:1;letter-spacing:-1.6px;font-variant-numeric:tabular-nums}
.tm-unit{font-size:clamp(10px,1.8vw,16px);font-weight:650;color:var(--tm-muted)}
.tm-capacity{display:flex;flex-direction:column;gap:1px;margin-top:5px}
.tm-capacity span{font-size:9px;color:var(--tm-muted)}
.tm-capacity strong{font-size:13px;font-weight:750;font-variant-numeric:tabular-nums}
.tm-state{display:flex;align-items:center;gap:6px;font-size:10px;font-weight:750;margin-top:5px}
.tm-scale{width:100%;flex:0 0 auto;padding:0 2px}
.tm-bar{height:9px;border-radius:8px;background:var(--tm-track);display:flex;overflow:hidden;position:relative}
.tm-bar-segment{height:100%;flex:0 0 auto}
.tm-bar-marker{position:absolute;top:-3px;width:3px;height:15px;background:var(--tm-text);border:1px solid var(--tm-bg);transform:translateX(-50%);box-shadow:0 0 3px #0008}
.tm-divisions{height:15px;position:relative;color:var(--tm-muted);font-size:8px}
.tm-divisions span{position:absolute;top:2px;transform:translateX(-50%);white-space:nowrap}
.tm-bar-labels{display:flex;font-size:8px;color:var(--tm-muted);text-align:center;line-height:11px}
.tm-bar-labels span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tm-level-mark{font-size:0;fill:transparent}
.tm-no-data{position:absolute;left:0;right:0;bottom:2px;text-align:center;color:var(--tm-muted);font-size:9px;pointer-events:none}
@media(max-width:210px){.tm-root{padding:5px}.tm-main{gap:2px}.tm-reading{min-width:70px}.tm-value{font-size:24px}.tm-capacity strong{font-size:10px}.tm-title{font-size:10px}}
@media(max-height:155px){.tm-root{padding:4px;gap:3px}.tm-header{min-height:15px}.tm-title{font-size:10px}.tm-main{min-height:65px}.tm-capacity{display:none}}
.tm-text-bottom .tm-main{flex-direction:column;justify-content:center;align-items:stretch;gap:2px}
.tm-text-bottom .tm-illustration{flex:1 1 0;width:100%;height:auto;min-height:70px}
.tm-text-bottom .tm-reading{flex:0 0 auto;width:100%;min-width:0;flex-direction:row;flex-wrap:wrap;align-items:center;justify-content:center;gap:2px 16px;text-align:center}
.tm-text-bottom .tm-reading-label{width:100%;text-align:center}
.tm-text-bottom .tm-value{font-size:clamp(24px,5vw,36px)}
.tm-text-bottom .tm-capacity{margin-top:0;align-items:flex-start}
.tm-text-bottom .tm-state{margin-top:0}

descriptor.controllerScript:
var tm = {dead:false, lastBuild:0, uid:'tm'+Math.random().toString(36).slice(2,8)};
function tmNum(v,d){var n=Number(v);return isFinite(n)&&v!==null&&v!==''?n:d;}
function tmClamp(v,a,b){return Math.max(a,Math.min(b,v));}
function tmEsc(s){return String(s===undefined||s===null?'':s);}
function tmFindSeries(data,keyName){
  for(var i=0;i<data.length;i++){
    var k=data[i]&&data[i].dataKey?data[i].dataKey:{};
    if((k.name||k.label)===keyName)return data[i];
  }
  return null;
}
function tmLastPoint(series){
  if(!series||!Array.isArray(series.data)||!series.data.length)return null;
  var p=series.data[series.data.length-1];
  if(!p||p.length<2)return null;
  var v=Number(p[1]);
  return isFinite(v)?{ts:Number(p[0]),value:v}:null;
}

function tmBool(v){
  if(typeof v==='boolean')return v;
  if(typeof v==='number')return isFinite(v)?v!==0:null;
  if(typeof v==='string'){
    var t=v.trim().toLowerCase();
    if(t==='true'||t==='1'||t==='on'||t==='yes'||t==='online'||t==='active')return true;
    if(t==='false'||t==='0'||t==='off'||t==='no'||t==='offline'||t==='inactive')return false;
  }
  return null;
}
function tmLastRaw(series){
  if(!series||!Array.isArray(series.data)||!series.data.length)return null;
  var p=series.data[series.data.length-1];
  return p&&p.length>=2?p[1]:null;
}
function tmSources(data){
  var main=null,conn=null,i,it,ki;
  for(i=0;i<data.length;i++){
    it=data[i];if(!it)continue;
    ki=typeof it.dataKeyIndex==='number'?it.dataKeyIndex:i;
    if(ki===0&&!main)main=it;else if(ki===1&&!conn)conn=it;
  }
  if(!main&&data.length)main=data[0];
  if(!conn){for(i=0;i<data.length;i++){if(data[i]&&data[i]!==main){conn=data[i];break;}}}
  return{main:main,conn:conn};
}
var TM_GEOM={
  vertical:{x0:122,x1:172,bottom:168,h:96},
  rectangular:{x0:97,x1:223,bottom:149,h:76},
  horizontal:{x0:35,x1:285,bottom:169,h:88},
  underground:{x0:35,x1:285,bottom:187,h:88},
  ibc:{x0:72,x1:248,bottom:176,h:132},
  elevated:{x0:92,x1:228,bottom:112,h:60},
  pressurized:{x0:136,x1:184,bottom:170,h:90},
  silo:{x0:100,x1:220,bottom:142,h:92},
  truck:{x0:105,x1:295,bottom:157,h:82},
  cistern:{x0:84,x1:236,bottom:182,h:110},
  undersquare:{x0:52,x1:268,bottom:190,h:84},
  reservoir:{x0:53,x1:267,bottom:179,h:78},
  round:{x0:102,x1:218,bottom:160,h:116},
  clarifier:{x0:30,x1:290,bottom:140,h:80},
  fueltruck:{x0:58,x1:262,bottom:168,h:86},
  hopper:{x0:82,x1:238,bottom:160,h:102},
  gascyl:{x0:139,x1:181,bottom:169,h:84},
  transformer:{x0:57,x1:263,bottom:109,h:68},
  stockpile:{x0:0,x1:10,bottom:10,h:10},
  battery:{x0:0,x1:10,bottom:10,h:10},
  pond:{x0:0,x1:10,bottom:10,h:10},
  silo_standing:{x0:136,x1:184,bottom:184,h:90},
  silo_hanging:{x0:113,x1:207,bottom:163,h:101}
};
function tmLiquid(g,ratio,has,solid){
  if(!has||ratio<=0.002)return{d:null,s:null};
  var top=g.bottom-g.h*ratio,x0=g.x0-4,x1=g.x1+4,n=4,w=(x1-x0)/n,amp=(solid||ratio>=0.995)?0:2.2;
  var s='M'+x0.toFixed(1)+' '+top.toFixed(1);
  for(var i=0;i<n;i++){
    s+=' Q'+(x0+w*i+w/2).toFixed(1)+' '+(top+(i%2===0?-amp:amp)).toFixed(1)+' '+(x0+w*(i+1)).toFixed(1)+' '+top.toFixed(1);
  }
  return{d:s+' V'+(g.bottom+6)+' H'+x0.toFixed(1)+' Z',s:s};
}
function tmPile(r){
  var ay=178-100*r,k=ay+(178-ay)*0.35;
  var d='M36 178 C96 176 132 '+k.toFixed(1)+' 160 '+ay.toFixed(1)+' C188 '+k.toFixed(1)+' 224 176 284 178 A124 24 0 0 1 36 178 Z';
  var rr='M160 '+ay.toFixed(1)+' C188 '+k.toFixed(1)+' 224 176 284 178 A124 24 0 0 1 160 202 Z';
  return{d:d,r:rr};
}
function tmUrls(u){
  return{m:'url(#'+u+'-m)',mv:'url(#'+u+'-mv)',sh:'url(#'+u+'-sh)',gl:'url(#'+u+'-gl)',clip:'url(#'+u+'-c)'};
}
function tmBuild(){
  var ctx=self.ctx,s=ctx.settings||{},data=ctx.data||[];
  var src=tmSources(data),mainSeries=src.main;
  var point=tmLastPoint(mainSeries),has=!!point;
  var min=tmNum(s.minValue,0),max=tmNum(s.maxValue,100);
  if(max<=min)max=min+1;
  var raw=has?point.value:min,ratio=tmClamp((raw-min)/(max-min),0,1);
  var pct=ratio*100;
  var decimals=tmClamp(tmNum(s.decimals,0),0,4);
  var display=has?pct.toFixed(decimals):'—';
  var tank=s.tankType||'vertical',fill=s.fillMode==='solid'?'solid':'liquid';
  if(s.fillMode===undefined&&s.contentType){
    if(s.contentType==='solid'){tank=s.tankTypeSolid||'hopper';fill='solid';}
    else if(s.contentType==='gas')tank=s.tankTypeGas||'gascyl';
    else if(s.contentType==='other')tank='battery';
  }
  if(!TM_GEOM[tank])tank='vertical';
  var ct=tank==='battery'?'other':fill,isSolid=ct==='solid';
  var geom=TM_GEOM[tank],lq=tmLiquid(geom,ratio,has,isSolid);
  var sections=Array.isArray(s.sections)&&s.sections.length?s.sections:[{color:'#D94B45',label:'CRÍTICO',status:'CRÍTICO'},{color:'#E6A23C',label:'BAJO',status:'BAJO'},{color:'#38A879',label:'NORMAL',status:'NORMAL'}];
  sections=sections.slice(0,12);
  var total=0;for(var j=0;j<sections.length;j++)total+=Math.max(0,tmNum(sections[j].width,1));
  if(total<=0)total=sections.length;
  var bar=[],cursor=0,active=sections[0]||{};
  for(var z=0;z<sections.length;z++){
    var sec=sections[z],w=Math.max(0,tmNum(sec.width,1))/total*100;
    bar.push({width:w,color:sec.color||'#38A879',label:sec.label||'',status:sec.status||sec.label||'',statusColor:sec.statusColor||sec.color||'#38A879'});
    if(pct>=cursor&&pct<=cursor+w)active=sec;
    cursor+=w;
  }
  var divisions=[];
  if(s.showDivisions){
    var count=tmClamp(tmNum(s.divisionCount,4),2,10);
    for(var q=0;q<=count;q++){
      var v=min+(max-min)*q/count;
      divisions.push({position:q/count*100,label:s.divisionAsPercent?Math.round(q/count*100)+'%':Number(v.toFixed(decimals)).toString()});
    }
  }
  var showOnline=s.onlineStatusEnabled===true,online=tmBool(tmLastRaw(src.conn))===true;
  var unit=s.unit||'';
  var readingText=has?raw.toLocaleString(undefined,{minimumFractionDigits:decimals,maximumFractionDigits:decimals})+(unit?' '+unit:''):'—';
  var capacityText=max.toLocaleString(undefined,{minimumFractionDigits:decimals,maximumFractionDigits:decimals})+(unit?' '+unit:'');
  var theme=s.theme||'industrial';
  self.ctx.$scope.vm={
    theme:theme,showHeader:s.showHeader!==false,showTitle:s.showTitle!==false,title:s.title||'Nivel de tanque',
    showIcon:s.showIcon===true,icon:s.icon||'opacity',showOnline:showOnline,online:online,
    tankType:tank,liquidColor:s.liquidColor||'#F2C300',
    hasData:has,displayValue:display,unit:'%',ratio:ratio,
    valueLabel:s.valueLabel||'NIVEL ACTUAL',levelLabel:'',
    showVolume:s.showVolume!==false,readingText:readingText,showCapacity:s.showCapacity!==false,capacityText:capacityText,
    showSegmentStatus:s.showSegmentStatus===true,activeStatus:active.status||active.label||'',activeStatusColor:active.statusColor||active.color||'#38A879',
    showBar:s.showBar!==false,barSegments:bar,showDivisions:s.showDivisions===true,divisions:divisions,
    showSegmentLabels:s.showSegmentLabels===true,
    showNoData:!has,noDataText:s.noDataText||'Sin datos',
    uid:tm.uid,u:tmUrls(tm.uid),liqD:lq.d,liqS:lq.s,clarDy:(80*(1-ratio)).toFixed(1),pondDy:(82*(1-ratio)).toFixed(1),emptyBed:has&&ratio<0.02,battW:(196*ratio).toFixed(1),pileD:tmPile(ratio).d,pileR:tmPile(ratio).r,iconStyle:s.iconStyle||'tank',contentType:ct,isSolid:isSolid,needleDeg:(-55+110*ratio).toFixed(1),textPosition:s.textPosition==='bottom'?'bottom':'side',
    showMinMax:s.showMinMax===true,minValue:min,maxValue:max
  };
  if(ctx.detectChanges)ctx.detectChanges();
}
self.onInit=function(){tm.dead=false;self.ctx.$scope.vm={theme:'industrial',tankType:'vertical',uid:tm.uid,u:tmUrls(tm.uid),barSegments:[],divisions:[],hasData:false,displayValue:'—',iconStyle:'tank',contentType:'liquid',isSolid:false,needleDeg:'-55',textPosition:'side'};tmBuild();};
self.onDataUpdated=function(){if(!tm.dead)tmBuild();};
self.onLatestDataUpdated=function(){if(!tm.dead)tmBuild();};
self.onResize=function(){if(!tm.dead)tmBuild();};
self.onDestroy=function(){tm.dead=true;};
self.typeParameters=function(){return{maxDatasources:1,maxDataKeys:2,datasourcesOptional:false,dataKeysOptional:false,previewWidth:'420px',previewHeight:'300px'};};

